IZO_st.name='IZO'; 
IZO_st.lat=28.309;
IZO_st.lon=-16.4994;
IZO_st.alt=2373;
IZO_st.env='Mt';
IZO_st.footp='Mx';
%%

IZO_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Izana.nc', IZO_st);

names_rd=fieldnames(IZO_rd);
%%
datevec(IZO_rd.Time(1)) % begin in 2006 %[output:22105f3d]
datevec(IZO_rd.Time(end)) % end in 2025 %[output:2074a562]
prctile(IZO_rd.UB_S,[5 50 95]) % < 30%, ok. RH trend was computed in 2019 due to change with time (ss decreasing RH), T controled at 20-22°C. %[output:6f8de7d3]

plotFigControl(IZO_rd,IZO_st.name); %[output:4bbd6528] %[output:11dd3d10] %[output:064346d6] %[output:4e9b69a0] %[output:978138c3] %[output:8ccebe4c] %[output:2ebfd978]
%%
% BP detection for scat coef and backscat

names_sc={'BsB0_S', 'BsG0_S', 'BsR0_S'};
break_IZO_scat_BP=change_point_analysis_Def(IZO_rd,names_sc,0.05,'IZO','scattering'); %[output:7e70fae6] %[output:0dea9256] %[output:98adeda4] %[output:4d46c6fe]
T_IZO_scat_BP=make_table_breakpoints_def(break_IZO_scat_BP);

names_bsc={'BbsB0_S', 'BbsG0_S', 'BbsR0_S'};
break_IZO_bscat_BP=change_point_analysis_Def(IZO_rd,names_bsc,0.05,'IZO','Backscattering'); %[output:719853f9] %[output:6694f122] %[output:834a5aca] %[output:7bf116f4]
T_IZO_bscat_BP=make_table_breakpoints_def(break_IZO_bscat_BP);
%%
% BP detection for abs
names_abs={'BaR0_A'};
break_IZO_abs_BP=change_point_analysis_Def(IZO_rd,names_abs,0.05,'IZO','Absorption'); %[output:982957b0] %[output:32305217]
T_IZO_abs_BP=make_table_breakpoints_def(break_IZO_abs_BP);
%%
lambdaSC=[450;550;700];
lambdaAE=637;
% % lambdaAE7=[370 470 520 590 660 880 950];
IZO_cal=compute_exp_SSA(IZO_rd,lambdaSC, lambdaAE);
plotFigControl_cal(IZO_cal, IZO_st.name); %[output:05b9cabc] %[output:4ade58b3] %[output:70a912d8]
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg0', 'expS_br0', 'expS_gr0'};
break_IZO_exps_BP=change_point_analysis_Def(IZO_cal,names_exps,0.05,'IZO','scattering exp'); %[output:8c55924a] %[output:237a11a9] %[output:7a944783] %[output:463914d5]
T_IZO_exps_BP=make_table_breakpoints_def(break_IZO_exps_BP);

names_BbF={'BbsFG'};
break_IZO_BbF_BP=change_point_analysis_Def(IZO_cal,names_BbF,0.05,'IZO','backscat fraction'); %[output:58744244] %[output:0569ff87]
T_IZO_BbF_BP=make_table_breakpoints_def(break_IZO_BbF_BP);

names_SSA={'SSA011'};
break_IZO_SSA_BP=change_point_analysis_Def(IZO_cal,names_SSA,0.05,'IZO','SSA'); %[output:69fb9df8] %[output:94ede2e8]
T_IZO_SSA_BP=make_table_breakpoints_def(break_IZO_SSA_BP);
%%
%Questions:
%problems:

%RH: it seems that there is a decrease of Humidity, is there any change in the drying process ?

%scat: there is a lot of long holes: are they real or due to databank problems ?

%%
IZO_tr=IZO_rd;
IZO_tr.y=year(IZO_tr.Time);
% begin at the beginning of a year: 2007 for abs, 2009 for scat
%end: 2025
P=timerange('2007-01-01','2026-01-01');
IZO_tr=IZO_tr(P,:);

% begin at the beginning of a year:  2009 for scat
Ps=timerange('2007-01-01','2009-01-01');
names=fieldnames(IZO_tr);
c=startsWith(names,["Bs";"Bbs";"U"]);
N=names(c) %[output:39c0fa94]
for i=1:length(N)
    IZO_tr.(N{i})(Ps)=NaN;
end

%change in RH: compute RH trend

% abs change for green wavelenght to compute SSA
IZO_tr.BaR_A11=IZO_tr.BaR0_A.*(637/550);
IZO_tr.BaR0_A=[];
IZO_cal2=compute_exp_SSA(IZO_tr,lambdaSC, lambdaAE);
IZO_tr=outerjoin(IZO_tr, IZO_cal2);

%do not compute trend on B, R and exp with red
IZO_tr.BsB0_S=[];
IZO_tr.BsR0_S=[];
IZO_tr.BbsB0_S=[];
IZO_tr.BbsR0_S=[];

IZO_tr.expS_br0=[]; %[output:9157b795]
IZO_tr.expS_gr0=[];
